// INVARIANT: two conditions, both required.

import { existsSync } from "node:fs";
import type { DatabaseSync } from "node:sqlite";

import { readConversationBlobMigrationState } from "./conversation-blob-db.js";

export type LegacyBlobRetirementDeferReason =
	| "store-closed"
	| "destination-unhealthy"
	| "adoption-incomplete"
	| "recovery-rebuilt"
	| "migration-state-unknown"
	| "root-missing"
	| "legacy-unreadable";

export interface LegacyBlobRetirementVerdict {
	readonly isRetirable: boolean;
	readonly reason?: LegacyBlobRetirementDeferReason;
	readonly legacyRows: number;
	readonly legacyBytes: number;
}

function defer(reason: LegacyBlobRetirementDeferReason): LegacyBlobRetirementVerdict {
	return { isRetirable: false, reason, legacyRows: 0, legacyBytes: 0 };
}

export interface LegacyBlobRetirementProofInput {
	readonly db: DatabaseSync;
	readonly legacyBlobDbPath: string;
	readonly retainedRootIdHex: string;
}

export function verifyLegacyBlobRetirement(
	options: LegacyBlobRetirementProofInput,
): LegacyBlobRetirementVerdict {
	const { db, legacyBlobDbPath, retainedRootIdHex } = options;
	if (!existsSync(legacyBlobDbPath)) return defer("legacy-unreadable");

	let quickCheck: string | undefined;
	try {
		quickCheck = (
			db.prepare("PRAGMA quick_check").get() as { readonly quick_check?: string } | undefined
		)?.quick_check;
	} catch {
		return defer("destination-unhealthy");
	}
	if (quickCheck !== "ok") return defer("destination-unhealthy");

	switch (readConversationBlobMigrationState(db)) {
		case "adoption-complete":
			break;
		case "unstarted":
			return defer("adoption-incomplete");
		case "recovery-rebuilt":
			return defer("recovery-rebuilt");
		default:
			return defer("migration-state-unknown");
	}

	const root = db.prepare("SELECT 1 AS present FROM blobs WHERE id = ?").get(retainedRootIdHex);
	if (root == null) return defer("root-missing");

	let isAttached = false;
	try {
		db.prepare("ATTACH DATABASE ? AS legacy").run(legacyBlobDbPath);
		isAttached = true;
		const totals = db
			.prepare("SELECT count(*) AS rows, coalesce(sum(length(data)), 0) AS bytes FROM legacy.blobs")
			.get() as { readonly rows?: unknown; readonly bytes?: unknown } | undefined;
		return {
			isRetirable: true,
			legacyRows: Number(totals?.rows ?? 0),
			legacyBytes: Number(totals?.bytes ?? 0),
		};
	} catch {
		// Any SQLite failure over the legacy side — an unattachable file, a torn
		// read, a lock that outlasted busy_timeout — leaves the store exactly as it
		// was and retries on the next eligible open. There is deliberately no path
		// that reports a partial answer.
		return defer("legacy-unreadable");
	} finally {
		if (isAttached) {
			try {
				db.exec("DETACH DATABASE legacy");
			} catch {}
		}
	}
}
