import type { DatabaseSync } from "node:sqlite";

import { fromHex, toHex, type BlobStore } from "@anysphere/agent-kv";
import type { Context } from "@anysphere/context";
import {
	ConversationStateStructure,
	ConversationTurnStructure,
	type ConversationState,
} from "@anysphere/proto/agent/v1/agent_pb.js";

import type { SandTranscriptEntry } from "../../../shared/transcript.js";
import { isGroupTurnPromptText } from "../../groups/group-chat.js";
import {
	deriveOutlineTurnsFromConversationState,
	type SandConversationOutlineItem,
} from "../../runner/conversation-outline.js";

const MAX_ROOT_BLOB_BYTES = 8 * 1024 * 1024;

interface BlobRow {
	readonly idHex: string;
	readonly data: Uint8Array;
}

interface RootScore {
	readonly turns: number;
	readonly rootPrompts: number;
	readonly bytes: number;
}

function scoreRootCandidate(data: Uint8Array, presentIds: ReadonlySet<string>): RootScore | null {
	if (data.length > MAX_ROOT_BLOB_BYTES) return null;
	let structure: ConversationStateStructure;
	try {
		structure = ConversationStateStructure.fromBinary(data);
	} catch {
		return null;
	}
	const turns = structure.turns;
	if (turns.length === 0) return null;
	for (const turnId of turns) {
		if (!presentIds.has(toHex(turnId))) return null;
	}
	return {
		turns: turns.length,
		rootPrompts: structure.rootPromptMessagesJson.length,
		bytes: data.length,
	};
}

function isBetterRoot(candidate: RootScore, best: RootScore | null): boolean {
	if (best == null) return true;
	if (candidate.turns !== best.turns) return candidate.turns > best.turns;
	if (candidate.rootPrompts !== best.rootPrompts) {
		return candidate.rootPrompts > best.rootPrompts;
	}
	return candidate.bytes > best.bytes;
}

export function selectLatestRootBlobIdHex(rows: readonly BlobRow[]): string | null {
	const presentIds = new Set(rows.map((row) => row.idHex));
	let bestId: string | null = null;
	let bestScore: RootScore | null = null;
	for (const row of rows) {
		const score = scoreRootCandidate(row.data, presentIds);
		if (score != null && isBetterRoot(score, bestScore)) {
			bestScore = score;
			bestId = row.idHex;
		}
	}
	return bestId;
}

// SAFETY: full-store scans stay on the worker; host scans wedge the box (SAND-459).
export function findLatestRootBlobIdInDatabase(db: DatabaseSync): Uint8Array | null {
	const presentIds = new Set<string>();
	const idStatement = db.prepare("SELECT id FROM blobs");
	for (const row of idStatement.iterate() as Iterable<{
		readonly id?: unknown;
	}>) {
		if (typeof row.id === "string") presentIds.add(row.id);
	}
	let bestId: string | null = null;
	let bestScore: RootScore | null = null;
	const blobStatement = db.prepare("SELECT id, data FROM blobs");
	for (const row of blobStatement.iterate() as Iterable<{
		readonly id?: unknown;
		readonly data?: unknown;
	}>) {
		if (typeof row.id !== "string" || !(row.data instanceof Uint8Array)) {
			continue;
		}
		const score = scoreRootCandidate(row.data, presentIds);
		if (score != null && isBetterRoot(score, bestScore)) {
			bestScore = score;
			bestId = row.id;
		}
	}
	return bestId != null ? fromHex(bestId) : null;
}

export function rebuildTranscriptEntriesFromState(state: ConversationState): SandTranscriptEntry[] {
	const entries: SandTranscriptEntry[] = [];
	for (const turn of deriveOutlineTurnsFromConversationState(state)) {
		if (turn.userMessageId.length === 0 && isGroupTurnPromptText(turn.rawUserText)) {
			continue;
		}
		for (const item of turn.items) {
			if (item.kind === "user") {
				if (item.hidden) continue;
				entries.push({
					kind: "message",
					id: `recovered-${item.id}`,
					role: "user",
					content: item.text,
					isStreaming: false,
				});
			} else if (item.kind === "send-message") {
				entries.push({
					kind: "send-message",
					id: `recovered-${item.id}`,
					message: item.message,
				});
			} else if (item.kind === "tool-call") {
				entries.push({
					kind: "tool-call",
					id: `recovered-${item.id}`,
					name: item.name,
					status: item.status,
					...(item.summary != null ? { summary: item.summary } : {}),
				});
			}
		}
	}
	return entries;
}

const REBUILT_ENTRY_ID_PREFIX = "recovered-";

export function selectHiddenArtifactEntryIds(
	entries: readonly SandTranscriptEntry[],
	outline: readonly SandConversationOutlineItem[],
): string[] {
	const outlineById = new Map(outline.map((item) => [item.id, item]));
	const ids: string[] = [];
	for (const entry of entries) {
		if (entry.kind !== "message" || entry.role !== "user") continue;
		if (!entry.id.startsWith(REBUILT_ENTRY_ID_PREFIX)) continue;
		const source = outlineById.get(entry.id.slice(REBUILT_ENTRY_ID_PREFIX.length));
		if (source?.kind === "user" && source.hidden === true && source.text === entry.content) {
			ids.push(entry.id);
		}
	}
	return ids;
}

export async function conversationStructureFullyResolves(
	ctx: Context,
	structure: ConversationStateStructure,
	blobStore: BlobStore,
): Promise<boolean> {
	if (structure.turns.length === 0) return false;
	for (const turnBlobId of structure.turns) {
		const turnBlob = await blobStore.getBlob(ctx, turnBlobId);
		if (!turnBlob) return false;
		let turnStructure: ConversationTurnStructure;
		try {
			turnStructure = ConversationTurnStructure.fromBinary(turnBlob);
		} catch {
			return false;
		}
		switch (turnStructure.turn.case) {
			case "agentConversationTurn": {
				const agentTurn = turnStructure.turn.value;
				if (!(await blobStore.getBlob(ctx, agentTurn.userMessage))) return false;
				for (const stepBlobId of agentTurn.steps) {
					if (!(await blobStore.getBlob(ctx, stepBlobId))) return false;
				}
				break;
			}
			case "shellConversationTurn": {
				const shellTurn = turnStructure.turn.value;
				if (!(await blobStore.getBlob(ctx, shellTurn.shellCommand))) return false;
				if (!(await blobStore.getBlob(ctx, shellTurn.shellOutput))) return false;
				break;
			}
			default:
				return false;
		}
	}
	for (const todoBlobId of structure.todos) {
		if (!(await blobStore.getBlob(ctx, todoBlobId))) return false;
	}
	if (structure.summary != null && structure.summary.length > 0) {
		if (!(await blobStore.getBlob(ctx, structure.summary))) return false;
	}
	return true;
}
