import { createHash } from "node:crypto";
import { existsSync } from "node:fs";
import type { DatabaseSync } from "node:sqlite";

import { ConversationStateStructure } from "@anysphere/proto/agent/v1/agent_pb.js";

import { findLatestRootBlobIdInDatabase } from "../extensions/session/conversation-recovery.js";
import {
	CONVERSATION_BLOB_ADOPTION_COMPLETE,
	openConversationBlobDb,
	readConversationBlobMigrationState,
} from "./conversation-blob-db.js";
import {
	verifyLegacyBlobRetirement,
	type LegacyBlobRetirementVerdict,
} from "./legacy-blob-retirement.js";

const MAX_STALE_ROOT_SCAN_BYTES = 64 * 1024 * 1024;

function toHex(bytes: Uint8Array): string {
	return Buffer.from(bytes.buffer, bytes.byteOffset, bytes.byteLength).toString("hex");
}

export interface ConversationBlobStoreDbOptions {
	readonly agentId: string;
	readonly blobDbPath: string;
	readonly busyTimeoutMs: number;
	readonly legacyBlobDbPath?: string;
	readonly log?: (message: string) => void;
}

export class ConversationBlobStoreDb {
	private readonly db: DatabaseSync;
	private readonly getBlobStmt: ReturnType<DatabaseSync["prepare"]>;
	private readonly setBlobStmt: ReturnType<DatabaseSync["prepare"]>;
	private readonly clearBlobsStmt: ReturnType<DatabaseSync["prepare"]>;
	// Held for the store's lifetime, not prepared inline at the scan, because
	// node:sqlite's row iterator does NOT keep its own StatementSync reachable:
	// once the statement is collected its sqlite3_stmt is finalized and the next
	// row throws ERR_INVALID_STATE ("statement has been finalized") mid-scan. A
	// bare local is not enough either — in an optimized frame V8 roots only
	// values that are still LIVE, and a local whose last use is `.iterate()` is
	// already dead at the loop's safepoints. Reachability from `this` is what
	// makes the whole iteration safe.
	private readonly scanBlobIndexStmt: ReturnType<DatabaseSync["prepare"]>;
	private isClosed = false;

	constructor(options: ConversationBlobStoreDbOptions) {
		const log = options.log ?? ((message) => console.error(message));
		this.db = openConversationBlobDb({
			dbPath: options.blobDbPath,
			agentId: options.agentId,
			busyTimeoutMs: options.busyTimeoutMs,
			log,
		});
		if (options.legacyBlobDbPath != null) {
			this.adoptLegacyBlobs(options.legacyBlobDbPath, log);
		}
		this.getBlobStmt = this.db.prepare("SELECT data FROM blobs WHERE id = ?");
		this.setBlobStmt = this.db.prepare(
			"INSERT INTO blobs (id, data) VALUES (?, ?) ON CONFLICT(id) DO UPDATE SET data = excluded.data",
		);
		this.clearBlobsStmt = this.db.prepare("DELETE FROM blobs");
		this.scanBlobIndexStmt = this.db.prepare("SELECT id, length(data) AS len FROM blobs");
	}

	private adoptLegacyBlobs(legacyBlobDbPath: string, log: (message: string) => void): void {
		const migrationState = readConversationBlobMigrationState(this.db);
		if (migrationState !== "unstarted" && migrationState !== "recovery-rebuilt") {
			return;
		}
		if (!existsSync(legacyBlobDbPath)) return;
		try {
			this.db.prepare("ATTACH DATABASE ? AS legacy").run(legacyBlobDbPath);
			try {
				this.db.exec("INSERT OR IGNORE INTO blobs (id, data) SELECT id, data FROM legacy.blobs");
			} finally {
				this.db.exec("DETACH DATABASE legacy");
			}
		} catch (error) {
			log(`[agent-store-worker] legacy blob adoption failed: ${String(error)}`);
			return;
		}
		this.db.exec(`PRAGMA user_version = ${CONVERSATION_BLOB_ADOPTION_COMPLETE}`);
	}

	getBlob(blobId: Uint8Array): Uint8Array | undefined {
		if (this.isClosed) return undefined;
		const row = this.getBlobStmt.get(toHex(blobId)) as { readonly data: Uint8Array } | undefined;
		return row?.data instanceof Uint8Array ? row.data : undefined;
	}

	findLatestRootBlobId(): Uint8Array | undefined {
		if (this.isClosed) return undefined;
		return findLatestRootBlobIdInDatabase(this.db) ?? undefined;
	}

	setBlob(blobId: Uint8Array, blobData: Uint8Array): void {
		if (this.isClosed) return;
		this.setBlobStmt.run(toHex(blobId), blobData);
	}

	clearBlobs(): void {
		if (this.isClosed) return;
		this.clearBlobsStmt.run();
	}

	// ONE-TIME cleanup of the stale checkpoint roots a store accumulated
	// before fixed-slot persistence; Sand has no resubmission or rewind, so
	// none is reachable product state. Deletion is decided by a conjunction of
	// independent proofs, each of which alone keeps live data safe:
	//   1. id == sha256(bytes) — written by the content-addressed writer;
	//   2. the bytes parse as a ConversationStateStructure whose every turn is
	//      a present blob in this store — the exact structural bar
	//      findLatestRootBlobIdInDatabase already trusts to ADOPT a root;
	//   3. the id is not `retainedRootIdHex` (the live root).
	// A root whose tree is incomplete is deliberately KEPT: deleting an
	// unprovable row is exactly what this predicate exists to forbid. The
	// first pass reads only `id` and `length(data)` (SQLite serves the length
	// from the record header without materializing the blob), so the giant
	// rows that make a store large are never read. The deletes run in one
	// transaction; re-running is an idempotent no-op. Runs on the worker
	// thread.
	clearStaleCheckpointRoots(retainedRootIdHex: string): number {
		if (this.isClosed) return 0;
		const presentIds = new Set<string>();
		const candidateIds: string[] = [];
		for (const row of this.scanBlobIndexStmt.iterate() as Iterable<{
			readonly id?: unknown;
			readonly len?: unknown;
		}>) {
			if (typeof row.id !== "string") continue;
			presentIds.add(row.id);
			if (
				row.id !== retainedRootIdHex &&
				typeof row.len === "number" &&
				row.len > 0 &&
				row.len <= MAX_STALE_ROOT_SCAN_BYTES
			) {
				candidateIds.push(row.id);
			}
		}
		const staleRootIds: string[] = [];
		for (const id of candidateIds) {
			const row = this.getBlobStmt.get(id) as { readonly data?: unknown } | undefined;
			const data = row?.data;
			if (!(data instanceof Uint8Array)) continue;
			if (createHash("sha256").update(data).digest("hex") !== id) continue;
			let structure: ConversationStateStructure;
			try {
				structure = ConversationStateStructure.fromBinary(data);
			} catch {
				continue;
			}
			if (structure.turns.length === 0) continue;
			const isWalkableRoot = structure.turns.every(
				(turnId) => turnId.length === 32 && presentIds.has(toHex(turnId)),
			);
			if (isWalkableRoot) staleRootIds.push(id);
		}
		if (staleRootIds.length === 0) return 0;
		const deleteBlobStmt = this.db.prepare("DELETE FROM blobs WHERE id = ?");
		let deleted = 0;
		let inTransaction = false;
		try {
			this.db.exec("BEGIN IMMEDIATE");
			inTransaction = true;
			for (const id of staleRootIds) {
				deleted += Number(deleteBlobStmt.run(id).changes);
			}
			this.db.exec("COMMIT");
		} catch (error) {
			if (inTransaction) this.db.exec("ROLLBACK");
			throw error;
		}
		return deleted;
	}

	verifyLegacyBlobRetirement(
		retainedRootIdHex: string,
		legacyBlobDbPath: string,
	): LegacyBlobRetirementVerdict {
		if (this.isClosed) {
			return {
				isRetirable: false,
				reason: "store-closed",
				legacyRows: 0,
				legacyBytes: 0,
			};
		}
		return verifyLegacyBlobRetirement({
			db: this.db,
			legacyBlobDbPath,
			retainedRootIdHex,
		});
	}

	close(): void {
		if (this.isClosed) return;
		this.isClosed = true;
		this.db.close();
	}
}
