import { copyFileSync, existsSync, renameSync, rmSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";

import { isSqliteCantOpenError, isSqliteCorruptError, isSqliteIoError } from "./sqlite-busy.js";
import { SQLITE_DB_SIDECAR_SUFFIXES } from "./store-db.js";

export interface SqliteQuarantineResult {
	readonly quarantinePath: string | null;
	readonly copied: boolean;
	readonly renameErrorCode: string | null;
}

export interface QuarantineCorruptSqliteDbOptions {
	readonly dbPath: string;
	readonly quarantinePath?: string;
	readonly preserveSourceOnCopyFailure?: boolean;
	readonly removeAttempts?: number;
	readonly removeRetryDelayMs?: number;
}

export function removeSqliteSidecars(dbPath: string): void {
	for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
		try {
			rmSync(`${dbPath}${suffix}`, { force: true, recursive: true });
		} catch {}
	}
}

function removePathWithRetries(options: {
	readonly path: string;
	readonly attempts?: number;
	readonly retryDelayMs?: number;
	readonly recursive?: boolean;
}): void {
	const attempts = Math.max(1, options.attempts ?? 1);
	let removeError: unknown;
	for (let attempt = 0; attempt < attempts; attempt += 1) {
		try {
			rmSync(options.path, {
				force: true,
				recursive: options.recursive === true,
			});
			removeError = undefined;
			break;
		} catch (error) {
			removeError = error;
			if (attempt < attempts - 1) {
				Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, options.retryDelayMs ?? 50);
			}
		}
	}
	if (removeError != null) throw removeError;
}

export function removeSqliteDb(options: {
	readonly dbPath: string;
	readonly attempts?: number;
	readonly retryDelayMs?: number;
}): void {
	removePathWithRetries({
		path: options.dbPath,
		attempts: options.attempts,
		retryDelayMs: options.retryDelayMs,
	});
	for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
		removePathWithRetries({
			path: `${options.dbPath}${suffix}`,
			attempts: options.attempts,
			retryDelayMs: options.retryDelayMs,
			recursive: true,
		});
	}
}

export function quarantineCorruptSqliteDb(
	options: QuarantineCorruptSqliteDbOptions,
): SqliteQuarantineResult {
	const { dbPath } = options;
	const stamp = new Date().toISOString().replace(/[:.]/g, "-");
	const quarantinePath = options.quarantinePath ?? `${dbPath}.corrupt-${stamp}`;
	try {
		rmSync(quarantinePath, { force: true });
		removeSqliteSidecars(quarantinePath);
	} catch {}

	try {
		renameSync(dbPath, quarantinePath);
	} catch (error) {
		const renameErrorCode = (error as NodeJS.ErrnoException).code ?? "error";
		let copied = false;
		try {
			copyFileSync(dbPath, quarantinePath);
			copied = true;
			for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
				const sidecar = `${dbPath}${suffix}`;
				if (existsSync(sidecar)) {
					try {
						copyFileSync(sidecar, `${quarantinePath}${suffix}`);
					} catch {}
				}
			}
		} catch {
			if (options.preserveSourceOnCopyFailure === true) {
				return {
					quarantinePath: dbPath,
					copied: false,
					renameErrorCode,
				};
			}
			copied = false;
		}
		removeSqliteDb({
			dbPath,
			attempts: options.removeAttempts,
			retryDelayMs: options.removeRetryDelayMs,
		});
		return {
			quarantinePath: copied ? quarantinePath : null,
			copied,
			renameErrorCode,
		};
	}

	for (const suffix of SQLITE_DB_SIDECAR_SUFFIXES) {
		try {
			const sidecar = `${dbPath}${suffix}`;
			if (existsSync(sidecar)) {
				renameSync(sidecar, `${quarantinePath}${suffix}`);
			}
		} catch {
			rmSync(`${dbPath}${suffix}`, { force: true });
		}
	}
	return { quarantinePath, copied: false, renameErrorCode: null };
}

export function openSqliteForSalvage(options: {
	readonly dbPath: string;
	readonly busyTimeoutMs?: number;
}): DatabaseSync | undefined {
	const { dbPath } = options;
	if (!existsSync(dbPath)) return undefined;
	const open = (): DatabaseSync => {
		const db = new DatabaseSync(dbPath);
		try {
			if (options.busyTimeoutMs != null) {
				db.exec(`PRAGMA busy_timeout = ${options.busyTimeoutMs}`);
			}
			// Force SQLite to read the header and any attached journal before
			// returning a handle; the constructor alone may defer that failure.
			db.prepare("PRAGMA schema_version").get();
			return db;
		} catch (error) {
			try {
				db.close();
			} catch {}
			throw error;
		}
	};
	try {
		return open();
	} catch (error) {
		if (!isSqliteIoError(error) && !isSqliteCantOpenError(error) && !isSqliteCorruptError(error)) {
			return undefined;
		}
		removeSqliteSidecars(dbPath);
		try {
			return open();
		} catch (retryError) {
			if (isSqliteCorruptError(retryError)) {
				try {
					return new DatabaseSync(dbPath);
				} catch {
					return undefined;
				}
			}
			return undefined;
		}
	}
}

export function copySalvageableSqliteRows(
	source: DatabaseSync,
	selectSql: string,
	insert: ReturnType<DatabaseSync["prepare"]>,
	toParams: (row: Record<string, unknown>) => unknown[],
): number {
	let iterator: IterableIterator<unknown>;
	try {
		iterator = source.prepare(selectSql).iterate() as IterableIterator<unknown>;
	} catch {
		return 0;
	}
	let copied = 0;
	try {
		for (;;) {
			let next: IteratorResult<unknown>;
			try {
				next = iterator.next();
			} catch {
				break;
			}
			if (next.done) break;
			try {
				insert.run(...(toParams(next.value as Record<string, unknown>) as never[]));
				copied += 1;
			} catch {}
		}
	} finally {
		try {
			iterator.return?.(undefined);
		} catch {}
	}
	return copied;
}
