const decoder = new TextDecoder();
const encoder = new TextEncoder();
export class Utf8Serde {
    serialize(value) {
        return encoder.encode(value);
    }
    deserialize(blob) {
        return decoder.decode(blob);
    }
    getBlobType() {
        return { kind: "string" };
    }
}
export const utf8Serde = new Utf8Serde();
export class ProtoSerde {
    constructor(proto) {
        this.proto = proto;
    }
    serialize(value) {
        return value.toBinary();
    }
    deserialize(blob) {
        return this.proto.fromBinary(blob);
    }
    getBlobType() {
        return { kind: "proto", typeName: this.proto.typeName };
    }
}
export function toHex(u8) {
    try {
        return Buffer.from(u8).toString("hex");
    }
    catch (error) {
        return Array.from(u8, b => b.toString(16).padStart(2, "0")).join("");
    }
}
export function fromHex(hex) {
    const clean = hex.trim().toLowerCase();
    if (clean.length % 2 !== 0)
        throw new Error("Invalid hex string length");
    const out = new Uint8Array(clean.length / 2);
    for (let i = 0; i < clean.length; i += 2) {
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        out[i / 2] = parseInt(clean.slice(i, i + 2), 16);
    }
    return out;
}
export function toBase64(u8) {
    try {
        return Buffer.from(u8).toString("base64");
    }
    catch (error) {
        // Fallback for browser/non-Node environments
        let binary = "";
        for (let i = 0; i < u8.length; i++) {
            binary += String.fromCharCode(u8[i]);
        }
        return btoa(binary);
    }
}
export function fromBase64(base64) {
    try {
        return new Uint8Array(Buffer.from(base64, "base64"));
    }
    catch (error) {
        // Fallback for browser/non-Node environments
        const binary = atob(base64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
            bytes[i] = binary.charCodeAt(i);
        }
        return bytes;
    }
}
